package cn.zhuatech.dealer.deep;import cn.zhuatech.dealer.model.AuditLog;import cn.zhuatech.dealer.repository.AuditLogRepository;import jakarta.persistence.*;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;
@Service @Transactional(readOnly=true) public class DeepDomainService{private final EntityManager em;private final AuditLogRepository logs;public DeepDomainService(EntityManager e,AuditLogRepository l){em=e;logs=l;}public Dashboard dashboard(String o){return new Dashboard(dealers(o),orders(o),rebates(o));}
 @Transactional public DealerView createDealer(DealerRequest r){var d=new DealerPartner(r.organizationCode(),r.dealerCode(),r.name(),r.taxNo(),r.agreementEnd());em.persist(d);audit("DEALER_ONBOARDING","登记经销商",d.dealerCode,d.name);return view(d);}@Transactional public DealerView submit(Long id){var d=dealer(id);state(d,"DRAFT");d.status="IN_REVIEW";audit("DEALER_ONBOARDING","提交准入",d.dealerCode,d.taxNo);return view(d);}@Transactional public DealerView approve(Long id,ApprovalRequest r){var d=dealer(id);state(d,"IN_REVIEW");if(r.creditLimit()<=0)throw bad("信用额度必须大于0");d.creditLimit=r.creditLimit();d.riskLevel=r.riskLevel();d.status="ACTIVE";audit("DEALER_ONBOARDING","批准准入",d.dealerCode,"credit="+r.creditLimit());return view(d);}
 @Transactional public AuthorizationView authorize(Long id,AuthorizationRequest r){var d=dealer(id);state(d,"ACTIVE");if(r.validTo().isBefore(r.validFrom()))throw bad("授权结束日不能早于开始日");var a=new TerritoryAuthorization(id,r.productCode(),r.regionCode(),r.minimumUnitPrice(),r.validFrom(),r.validTo());em.persist(a);audit("DEALER_AUTH","建立区域授权",d.dealerCode,r.productCode()+"/"+r.regionCode());return view(a);}
 @Transactional public OrderView order(OrderRequest r){var d=dealer(r.dealerId());state(d,"ACTIVE");if(d.agreementEnd!=null&&r.orderDate().isAfter(d.agreementEnd))throw conflict("经销协议已到期");var a=em.createQuery("select a from TerritoryAuthorization a where a.dealerId=:d and a.productCode=:p and a.regionCode=:r and a.status='ACTIVE' and a.validFrom<=:dt and a.validTo>=:dt",TerritoryAuthorization.class).setParameter("d",d.id).setParameter("p",r.productCode()).setParameter("r",r.regionCode()).setParameter("dt",r.orderDate()).getResultStream().findFirst().orElse(null);if(a==null)throw conflict("订单产品或区域未授权");if(r.unitPrice()<a.minimumUnitPrice)throw conflict("订单价格低于渠道最低成交价");double total=r.quantity()*r.unitPrice();if(d.creditUsed+total>d.creditLimit)throw conflict("订单超过可用信用额度");var o=new ChannelOrder(d.id,r.orderNo(),r.productCode(),r.regionCode(),r.quantity(),r.unitPrice(),r.orderDate());em.persist(o);audit("CHANNEL_ORDER","创建渠道订单",o.orderNo,"amount="+o.totalAmount);return view(o);}
 @Transactional public OrderView approveOrder(Long id){var o=order(id);state(o,"PENDING_APPROVAL");var d=dealer(o.dealerId);if(d.creditUsed+o.totalAmount>d.creditLimit)throw conflict("审批时可用信用额度不足");d.creditUsed+=o.totalAmount;o.status="APPROVED";audit("CHANNEL_ORDER","批准渠道订单",o.orderNo,"creditUsed="+d.creditUsed);return view(o);}@Transactional public OrderView fulfill(Long id){var o=order(id);state(o,"APPROVED");o.status="FULFILLED";audit("CHANNEL_ORDER","订单履约",o.orderNo,o.regionCode);return view(o);}
 @Transactional public RebateView claim(Long id,RebateRequest r){var o=order(id);state(o,"FULFILLED");if(r.claimAmount()>o.totalAmount*.2)throw conflict("返利申请超过订单金额20%的控制上限");var x=new RebateClaim(id,r.claimNo(),r.claimAmount());em.persist(x);audit("DEALER_REBATE","提交返利申请",x.claimNo,"amount="+x.claimAmount);return view(x);}@Transactional public RebateView settle(Long id,SettleRequest r){var x=rebate(id);if(!"SUBMITTED".equals(x.status))throw conflict("返利申请状态不可结算");if(r.approvedAmount()>x.claimAmount)throw bad("批准金额不能超过申请金额");x.approvedAmount=r.approvedAmount();x.status="SETTLED";audit("DEALER_REBATE","结算返利",x.claimNo,"approved="+x.approvedAmount);return view(x);}
 private List<DealerView> dealers(String o){return em.createQuery("select d from DealerPartner d where d.organizationCode=:o order by d.createdAt desc",DealerPartner.class).setParameter("o",o).getResultList().stream().map(this::view).toList();}private List<OrderView> orders(String o){return em.createQuery("select x from ChannelOrder x where x.dealerId in(select d.id from DealerPartner d where d.organizationCode=:o) order by x.createdAt desc",ChannelOrder.class).setParameter("o",o).getResultList().stream().map(this::view).toList();}private List<RebateView> rebates(String o){return em.createQuery("select x from RebateClaim x where x.orderId in(select y.id from ChannelOrder y where y.dealerId in(select d.id from DealerPartner d where d.organizationCode=:o)) order by x.createdAt desc",RebateClaim.class).setParameter("o",o).getResultList().stream().map(this::view).toList();}private DealerPartner dealer(Long id){var x=em.find(DealerPartner.class,id);if(x==null)throw missing("经销商不存在");return x;}private ChannelOrder order(Long id){var x=em.find(ChannelOrder.class,id);if(x==null)throw missing("渠道订单不存在");return x;}private RebateClaim rebate(Long id){var x=em.find(RebateClaim.class,id);if(x==null)throw missing("返利申请不存在");return x;}private void state(DealerPartner d,String s){if(!s.equals(d.status))throw conflict("当前经销商状态不能执行该操作");}private void state(ChannelOrder o,String s){if(!s.equals(o.status))throw conflict("当前订单状态不能执行该操作");}private void audit(String m,String a,String n,String d){logs.save(new AuditLog(m,a,n,"dealer-domain",d));}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException missing(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
 private DealerView view(DealerPartner d){return new DealerView(d.id,d.organizationCode,d.dealerCode,d.name,d.taxNo,d.status,d.creditLimit,d.creditUsed,d.riskLevel,d.agreementEnd,d.version);}private AuthorizationView view(TerritoryAuthorization a){return new AuthorizationView(a.id,a.dealerId,a.productCode,a.regionCode,a.minimumUnitPrice,a.validFrom,a.validTo,a.status);}private OrderView view(ChannelOrder o){return new OrderView(o.id,o.dealerId,o.orderNo,o.productCode,o.regionCode,o.quantity,o.unitPrice,o.totalAmount,o.status,o.orderDate,o.version);}private RebateView view(RebateClaim r){return new RebateView(r.id,r.orderId,r.claimNo,r.claimAmount,r.approvedAmount,r.status);}
 public record DealerRequest(@NotBlank String organizationCode,@NotBlank String dealerCode,@NotBlank String name,@NotBlank String taxNo,@NotNull LocalDate agreementEnd){}public record ApprovalRequest(@Positive double creditLimit,@NotBlank String riskLevel){}public record AuthorizationRequest(@NotBlank String productCode,@NotBlank String regionCode,@PositiveOrZero double minimumUnitPrice,@NotNull LocalDate validFrom,@NotNull LocalDate validTo){}public record OrderRequest(@NotNull Long dealerId,@NotBlank String orderNo,@NotBlank String productCode,@NotBlank String regionCode,@Positive int quantity,@Positive double unitPrice,@NotNull LocalDate orderDate){}public record RebateRequest(@NotBlank String claimNo,@Positive double claimAmount){}public record SettleRequest(@PositiveOrZero double approvedAmount){}public record DealerView(Long id,String organizationCode,String dealerCode,String name,String taxNo,String status,double creditLimit,double creditUsed,String riskLevel,LocalDate agreementEnd,long version){}public record AuthorizationView(Long id,Long dealerId,String productCode,String regionCode,double minimumUnitPrice,LocalDate validFrom,LocalDate validTo,String status){}public record OrderView(Long id,Long dealerId,String orderNo,String productCode,String regionCode,int quantity,double unitPrice,double totalAmount,String status,LocalDate orderDate,long version){}public record RebateView(Long id,Long orderId,String claimNo,double claimAmount,double approvedAmount,String status){}public record Dashboard(List<DealerView> dealers,List<OrderView> orders,List<RebateView> rebates){}
}
